import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { FiAward } from "react-icons/fi";

import DashboardLayout from "../../layouts/DashboardLayout";
import Card from "../../components/Card";
import FormField from "../../components/FormField";

import { gradeApi } from "../../api/gradeApi";
import { studentApi } from "../../api/studentApi";
import { registrationApi } from "../../api/registrationApi";

import { useToast } from "../../context/ToastContext";
import { extractErrorMessage } from "../../api/axios";

import {
  validateFields,
  isRequired
} from "../../utils/validators";

import { fullName } from "../../utils/formatters";


// ============================================================
// GRADE OPTIONS
// ============================================================

const GRADE_OPTIONS = [
  "A",
  "A-",
  "B+",
  "B",
  "B-",
  "C+",
  "C",
  "C-",
  "D",
  "F"
].map((grade) => ({
  value: grade,
  label: grade
}));


// ============================================================
// INITIAL FORM VALUES
// ============================================================

const initialValues = {
  student_id: "",
  registration_id: "",
  grade: "",
  remark: ""
};


// ============================================================
// ASSIGN GRADE PAGE
// ============================================================

export default function AssignGrade() {
  const navigate = useNavigate();
  const toast = useToast();

  // ----------------------------------------------------------
  // FORM STATE
  // ----------------------------------------------------------

  const [values, setValues] = useState(initialValues);
  const [errors, setErrors] = useState({});

  // ----------------------------------------------------------
  // STUDENTS
  // ----------------------------------------------------------

  const [students, setStudents] = useState([]);
  const [loadingStudents, setLoadingStudents] = useState(true);

  // ----------------------------------------------------------
  // REGISTERED COURSES
  // ----------------------------------------------------------

  const [registrationOptions, setRegistrationOptions] = useState([]);
  const [loadingRegistrations, setLoadingRegistrations] =
    useState(false);

  // ----------------------------------------------------------
  // SUBMIT
  // ----------------------------------------------------------

  const [isSubmitting, setIsSubmitting] = useState(false);


  // ==========================================================
  // LOAD STUDENTS
  // ==========================================================

  useEffect(() => {
    let mounted = true;

    async function loadStudents() {
      setLoadingStudents(true);

      try {
        const response = await studentApi.getAll();

        if (!mounted) return;

        console.log(
          "STUDENT API RESPONSE:",
          response.data
        );

        const data = response?.data;

        let studentList = [];

        // Your backend returns:
        //
        // {
        //   success: true,
        //   total: 2,
        //   students: [...]
        // }

        if (Array.isArray(data?.students)) {
          studentList = data.students;
        }

        // Fallback
        else if (Array.isArray(data?.data)) {
          studentList = data.data;
        }

        // Fallback
        else if (Array.isArray(data)) {
          studentList = data;
        }

        setStudents(studentList);

      } catch (error) {
        if (!mounted) return;

        console.error(
          "LOAD STUDENTS ERROR:",
          error
        );

        setStudents([]);

        toast.error(
          extractErrorMessage(
            error,
            "Unable to load students."
          )
        );

      } finally {
        if (mounted) {
          setLoadingStudents(false);
        }
      }
    }

    loadStudents();

    return () => {
      mounted = false;
    };
  }, [toast]);


  // ==========================================================
  // STUDENT OPTIONS
  // ==========================================================

  const studentOptions = students
    .map((student) => {

      // IMPORTANT:
      // Backend uses student_id, not id.

      const studentId = student?.student_id;

      if (!studentId) {
        return null;
      }

      const name = fullName(student);

      const registrationNumber =
        student?.registration_number || "";

      return {
        value: String(studentId),

        label: registrationNumber
          ? `${name} — ${registrationNumber}`
          : name
      };
    })
    .filter(Boolean);


  // ==========================================================
  // LOAD REGISTERED COURSES
  // ==========================================================

  useEffect(() => {
    let mounted = true;

    async function loadRegistrations() {

      // No student selected
      if (!values.student_id) {
        setRegistrationOptions([]);
        setLoadingRegistrations(false);
        return;
      }

      setLoadingRegistrations(true);
      setRegistrationOptions([]);

      try {

        console.log(
          "LOADING REGISTRATIONS FOR STUDENT:",
          values.student_id
        );

        const response =
          await registrationApi.getByStudent(
            values.student_id
          );

        if (!mounted) return;

        console.log(
          "REGISTRATION API RESPONSE:",
          response.data
        );

        const data = response?.data;

        let registrations = [];

        /*
          Support these possible backend responses:

          {
            success: true,
            registrations: [...]
          }

          OR

          {
            success: true,
            courses: [...]
          }

          OR

          {
            success: true,
            data: [...]
          }
        */

        if (Array.isArray(data?.registrations)) {
          registrations = data.registrations;
        }

        else if (Array.isArray(data?.courses)) {
          registrations = data.courses;
        }

        else if (Array.isArray(data?.data)) {
          registrations = data.data;
        }

        else if (Array.isArray(data)) {
          registrations = data;
        }


        // ------------------------------------------------------
        // Convert registrations into select options
        // ------------------------------------------------------

        const options = registrations
          .map((registration) => {

            /*
              Your student_courses table uses:

              id
              student_id
              course_id
              semester
              academic_year
            */

            const registrationId =
              registration?.id ??
              registration?.student_course_id ??
              registration?.registration_id;

            if (!registrationId) {
              return null;
            }


            // Course code
            const courseCode =
              registration?.course_code ??
              registration?.course?.course_code ??
              registration?.code ??
              registration?.course?.code ??
              "";


            // Course name
            const courseName =
              registration?.course_name ??
              registration?.course?.course_name ??
              registration?.name ??
              registration?.course?.name ??
              "";


            // Semester
            const semester =
              registration?.semester || "";


            // Academic year
            const academicYear =
              registration?.academic_year || "";


            // --------------------------------------------------
            // Create readable label
            // --------------------------------------------------

            let label = "";

            if (courseCode && courseName) {
              label =
                `${courseCode} — ${courseName}`;
            }

            else if (courseCode) {
              label = courseCode;
            }

            else if (courseName) {
              label = courseName;
            }

            else {
              label =
                `Course Registration #${registrationId}`;
            }


            if (semester || academicYear) {

              label += ` (${semester}${
                semester && academicYear
                  ? ", "
                  : ""
              }${academicYear})`;

            }


            return {
              value: String(registrationId),
              label
            };

          })
          .filter(Boolean);


        setRegistrationOptions(options);

      } catch (error) {

        if (!mounted) return;

        console.error(
          "LOAD REGISTRATIONS ERROR:",
          error
        );

        setRegistrationOptions([]);

        toast.error(
          extractErrorMessage(
            error,
            "Unable to load registered courses."
          )
        );

      } finally {

        if (mounted) {
          setLoadingRegistrations(false);
        }

      }
    }

    loadRegistrations();

    return () => {
      mounted = false;
    };

  }, [values.student_id, toast]);


  // ==========================================================
  // HANDLE INPUT CHANGE
  // ==========================================================

  function handleChange(event) {

    const {
      name,
      value
    } = event.target;


    // --------------------------------------------------------
    // Student changed
    // --------------------------------------------------------

    if (name === "student_id") {

      setValues((previous) => ({
        ...previous,

        student_id: value,

        // Clear previous course
        registration_id: ""
      }));


      setErrors((previous) => ({
        ...previous,

        student_id: "",
        registration_id: ""
      }));

      return;
    }


    // --------------------------------------------------------
    // Other fields
    // --------------------------------------------------------

    setValues((previous) => ({
      ...previous,
      [name]: value
    }));


    setErrors((previous) => ({
      ...previous,
      [name]: ""
    }));

  }


  // ==========================================================
  // SUBMIT
  // ==========================================================

  async function handleSubmit(event) {

    event.preventDefault();


    // --------------------------------------------------------
    // Validate
    // --------------------------------------------------------

    const fieldErrors = validateFields(
      values,
      {
        student_id: [isRequired],
        registration_id: [isRequired],
        grade: [isRequired]
      }
    );


    if (Object.keys(fieldErrors).length > 0) {

      setErrors(fieldErrors);

      toast.error(
        "Please complete all required fields."
      );

      return;
    }


    setIsSubmitting(true);


    try {

      /*
        IMPORTANT:

        Backend controller expects:

        {
          student_course_id,
          grade,
          remark
        }

        So we DO NOT send student_id
        or registration_id to the backend.
      */

      const payload = {

        student_course_id:
          Number(values.registration_id),

        grade:
          values.grade,

        remark:
          values.remark?.trim() || null
      };


      console.log(
        "ASSIGN GRADE PAYLOAD:",
        payload
      );


      // ------------------------------------------------------
      // POST /api/grades
      // ------------------------------------------------------

      await gradeApi.assign(payload);


      toast.success(
        "Grade assigned successfully."
      );


      // ------------------------------------------------------
      // Go to student's grade page
      // ------------------------------------------------------

      navigate(
        `/grades/student/${values.student_id}`
      );


    } catch (error) {

      console.error(
        "ASSIGN GRADE ERROR:",
        error
      );

      toast.error(
        extractErrorMessage(
          error,
          "Unable to assign this grade."
        )
      );

    } finally {

      setIsSubmitting(false);

    }

  }


  // ==========================================================
  // PAGE
  // ==========================================================

  return (
    <DashboardLayout>

      <div className="max-w-lg mx-auto">

        {/* ====================================================
            PAGE HEADER
        ==================================================== */}

        <div className="flex items-center gap-2 mb-6">

          <div
            className="
              h-9
              w-9
              rounded-lg
              bg-navy-100
              text-navy-700
              flex
              items-center
              justify-center
            "
          >

            <FiAward size={16} />

          </div>


          <h1
            className="
              font-display
              text-xl
              text-navy-800
            "
          >
            Assign Grade
          </h1>

        </div>


        {/* ====================================================
            FORM CARD
        ==================================================== */}

        <Card className="p-6">

          <form
            onSubmit={handleSubmit}
            className="space-y-4"
            noValidate
          >

            {/* =================================================
                STUDENT
            ================================================= */}

            <FormField
              as="select"
              label="Student"
              name="student_id"
              value={values.student_id}
              onChange={handleChange}
              error={errors.student_id}
              required
              options={studentOptions}
              placeholder={
                loadingStudents
                  ? "Loading students..."
                  : studentOptions.length === 0
                  ? "No students available"
                  : "Select a student"
              }
            />


            {/* =================================================
                COURSE REGISTRATION
            ================================================= */}

            <FormField
              as="select"
              label="Course Registration"
              name="registration_id"
              value={values.registration_id}
              onChange={handleChange}
              error={errors.registration_id}
              required
              disabled={
                !values.student_id ||
                loadingRegistrations
              }
              options={registrationOptions}
              placeholder={
                !values.student_id
                  ? "Select a student first"
                  : loadingRegistrations
                  ? "Loading registered courses..."
                  : registrationOptions.length === 0
                  ? "No registered courses found"
                  : "Select a course registration"
              }
            />


            {/* =================================================
                GRADE
            ================================================= */}

            <FormField
              as="select"
              label="Grade"
              name="grade"
              value={values.grade}
              onChange={handleChange}
              error={errors.grade}
              required
              options={GRADE_OPTIONS}
              placeholder="Select grade"
            />


            {/* =================================================
                REMARK
            ================================================= */}

            <FormField
              as="textarea"
              label="Remark"
              name="remark"
              value={values.remark}
              onChange={handleChange}
              error={errors.remark}
              placeholder="Optional note about this grade"
            />


            {/* =================================================
                BUTTONS
            ================================================= */}

            <div className="flex gap-3 pt-2">

              <button
                type="button"
                onClick={() => navigate("/grades")}
                disabled={isSubmitting}
                className="
                  flex-1
                  py-2.5
                  rounded-lg
                  text-sm
                  border
                  border-line
                  text-ink
                  hover:bg-paper
                  transition
                  disabled:opacity-60
                "
              >
                Cancel
              </button>


              <button
                type="submit"
                disabled={
                  isSubmitting ||
                  loadingStudents ||
                  loadingRegistrations ||
                  !values.student_id ||
                  !values.registration_id
                }
                className="
                  flex-1
                  py-2.5
                  rounded-lg
                  text-sm
                  bg-navy-700
                  text-white
                  hover:bg-navy-800
                  transition
                  disabled:opacity-60
                "
              >

                {isSubmitting
                  ? "Saving..."
                  : "Assign Grade"}

              </button>

            </div>

          </form>

        </Card>

      </div>

    </DashboardLayout>
  );
}
